ctx.globalAlpha = Math.min(1, hintT);
txt(ctx, lockFails >= 2 && !lockOk ? 'Click and drag to look  ·  Arrow keys + F aim and fire' : 'Click to lock the mouse  ·  or drag to look  ·  Arrow keys + F aim and fire',
LW / 2, LH - 100, 14, FONT_B, UI.body, 'center', 600, '600');
ctx.globalAlpha = 1;
