const IT = { page: ['open', 'back'], host: ['wave', 'start', 'leave'], guest: [], res: ['again', 'leave'], menu: ['resume', 'leave'] };
const NAVK = { ArrowUp: -1, ArrowDown: 1, ArrowLeft: -1, ArrowRight: 1, Enter: 2, NumpadEnter: 2, Space: 2, Escape: 3, KeyP: 3 };
function items() { return mode === 'title' ? (scr === 'online' ? IT.page : net && net.host ? IT.host : IT.guest) : mode === 'over' ? IT.res : IT.menu; }
function openNetMenu() { if (!netMenu) { netMenu = true; nfocus = 0; clearInput(); releaseLock(); } }
function netAct(id, dir) {
click();
if (id === 'open') netOpen();
else if (id === 'back') { scr = 'title'; netNote = ''; }
else if (id === 'wave') { ncfg.w = (ncfg.w + dir + START_WAVES.length) % START_WAVES.length; netCfg(); }
else if (id === 'start') netStart();
else if (id === 'leave') netLeave('');
else if (id === 'again') { mode = 'title'; NR = null; nfocus = 1; clearWorld(); netStart(); }
else if (id === 'resume') netMenu = false;
}
function netKey(c, e) { // true when the key is used
if (mode === 'title' && scr === 'title') { e.preventDefault(); if (!e.repeat && NET_OK) toPage(); return true; }
const it = items(), n = it.length, nk = NAVK[c];
if (mode === 'playing' && !netMenu) {
if (nk !== 3) return false;
e.preventDefault();
if (!e.repeat) openNetMenu();
return true;
}
if (!nk) return true;
e.preventDefault();
if (!(nfocus >= 0 && nfocus < n)) nfocus = 0;
const id = it[nfocus], ud = c === 'ArrowUp' || c === 'ArrowDown';
if ((e.repeat && !ud) || (mode === 'over' && !overReady()) || netOpening) return true;
if (nk === 3) { if (mode === 'playing') netAct('resume'); else if (c === 'Escape') netAct(scr === 'online' && mode === 'title' ? 'back' : 'leave'); }
else if (nk === 2) { if (n) netAct(id, 1); }
else if (id === 'wave' && !ud) netAct(id, nk);
else if (n) nfocus = (nfocus + nk + n) % n;
return true;
}
function netPointer(cx, cy, touch) { // true when used
const p = toLogical(cx, cy, 0.5, 0.5);
if (mode === 'title' && scr === 'title') {
if (p.x < OBTN.x || p.x > OBTN.x + OBTN.w || p.y < OBTN.y || p.y > OBTN.y + OBTN.h) return false;
if (NET_OK) toPage();
return true;
}
if ((mode === 'over' && !overReady()) || netOpening) return true;
for (let i = 0; i < btnN; i++) {
const b = btns[i];
if (p.x < b.x || p.x > b.x + b.w || p.y < b.y || p.y > b.y + b.h) continue;
nfocus = b.f;
netAct(b.id, 1);
if (mode === 'playing' && !netMenu && !touch) requestLock();
break;
}
return true;
}

