function prep(geo,hex,k){
let g=geo;
if(g.index){g=geo.toNonIndexed();geo.dispose();}
g.computeVertexNormals();
const n=g.attributes.position.count,col=new Float32Array(n*3),m=k==null?1:k;
tmpC.set(hex);
for(let i=0;i<n;i++){col[i*3]=tmpC.r*m;col[i*3+1]=tmpC.g*m;col[i*3+2]=tmpC.b*m;}
g.setAttribute('color',new THREE.BufferAttribute(col,3));
return g;
}
function merge(list){
let n=0;
for(let i=0;i<list.length;i++)n+=list[i].attributes.position.count;
const pos=new Float32Array(n*3),nor=new Float32Array(n*3),col=new Float32Array(n*3);
let o=0;
for(let i=0;i<list.length;i++){
const g=list[i];
pos.set(g.attributes.position.array,o);nor.set(g.attributes.normal.array,o);col.set(g.attributes.color.array,o);
o+=g.attributes.position.count*3;
g.dispose();
}
const m=new THREE.BufferGeometry();
m.setAttribute('position',new THREE.BufferAttribute(pos,3));
m.setAttribute('normal',new THREE.BufferAttribute(nor,3));
m.setAttribute('color',new THREE.BufferAttribute(col,3));
m.computeBoundingSphere();
return m;
}
function part(list,geo,hex,k){list.push(prep(geo,hex,k));}
function box(w,h,d,x,y,z){const g=new THREE.BoxGeometry(w,h,d);g.translate(x,y,z);return g;}
function cylX(r,len,seg,x,y,z){const g=new THREE.CylinderGeometry(r,r,len,seg);g.rotateZ(Math.PI/2);g.translate(x,y,z);return g;}
function cylZ(r1,r2,len,seg,x,y,z){const g=new THREE.CylinderGeometry(r1,r2,len,seg);g.rotateX(Math.PI/2);g.translate(x,y,z);return g;}
function cylY(r1,r2,len,seg,x,y,z){const g=new THREE.CylinderGeometry(r1,r2,len,seg);g.translate(x,y,z);return g;}
function rot(g,rx,ry,rz){if(rx)g.rotateX(rx);if(ry)g.rotateY(ry);if(rz)g.rotateZ(rz);return g;}
function mv(g,x,y,z){g.translate(x,y,z);return g;}

