const ims=[];
function makeIM(geo,mat,cap,parent){
const m=new THREE.InstancedMesh(geo,mat,cap);
m.frustumCulled=false;
tmpC.setRGB(1,1,1);
for(let i=0;i<cap;i++){m.setMatrixAt(i,ZERO_M);m.setColorAt(i,tmpC);}
m.instanceMatrix.needsUpdate=true;
if(m.instanceColor)m.instanceColor.needsUpdate=true;
(parent||scene).add(m);
ims.push(m);
return m;
}
function upd(m){m.instanceMatrix.needsUpdate=true;if(m.instanceColor)m.instanceColor.needsUpdate=true;}
function setI(m,i,x,y,z,ry,sx,sy,sz){
dummy.position.set(x,y,z);dummy.rotation.set(0,ry,0);dummy.scale.set(sx,sy,sz);
dummy.updateMatrix();m.setMatrixAt(i,dummy.matrix);
}
function setIR(m,i,x,y,z,rx,ry,rz,sx,sy,sz){
dummy.position.set(x,y,z);dummy.rotation.set(rx,ry,rz,'YXZ');dummy.scale.set(sx,sy,sz);
dummy.updateMatrix();m.setMatrixAt(i,dummy.matrix);
}
function hideI(m,i){m.setMatrixAt(i,ZERO_M);}
function colI(m,i,r,g,b){tmpC.setRGB(r,g,b);m.setColorAt(i,tmpC);}

