const PS_VS=[
'attribute vec4 tint;','attribute float size;','uniform float uScale;','varying vec4 vTint;','#include <fog_pars_vertex>',
'void main() {','  vTint = tint;','  vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);',
'  gl_PointSize = size * uScale / max(-mvPosition.z, 0.5);','  gl_Position = projectionMatrix * mvPosition;','  #include <fog_vertex>','}'].join('\n');
const PS_FS=[
'uniform sampler2D uMap;','varying vec4 vTint;','#include <fog_pars_fragment>',
'void main() {','  float a = texture2D(uMap, gl_PointCoord).a * vTint.a;','  if (a < 0.01) discard;',
'  gl_FragColor = vec4(vTint.rgb, a);','  #include <fog_fragment>','}'].join('\n');
const PF=['x','y','z','vx','vy','vz','life','max','s0','s1','r','g','b','a','drag','grav'];
function makePS(cap,additive){
const geo=keep(new THREE.BufferGeometry());
const ps={cap:cap,n:0,add:additive,pos:new Float32Array(cap*3),tint:new Float32Array(cap*4),size:new Float32Array(cap)};
for(let i=0;i<PF.length;i++)ps[PF[i]]=new Float32Array(cap);
geo.setAttribute('position',new THREE.BufferAttribute(ps.pos,3));
geo.setAttribute('tint',new THREE.BufferAttribute(ps.tint,4));
geo.setAttribute('size',new THREE.BufferAttribute(ps.size,1));
geo.setDrawRange(0,0);
const un=THREE.UniformsUtils.merge([THREE.UniformsLib.fog]);
un.uMap={value:puffTex};un.uScale={value:300};
const mat=keep(new THREE.ShaderMaterial({uniforms:un,vertexShader:PS_VS,fragmentShader:PS_FS,transparent:true,depthWrite:false,
blending:additive?THREE.AdditiveBlending:THREE.NormalBlending,fog: !additive}));
const pts=new THREE.Points(geo,mat);pts.frustumCulled=false;pts.renderOrder=additive?4:3;
scene.add(pts);
ps.geo=geo;ps.mat=mat;ps.pts=pts;
return ps;
}
const fxA=makePS(760,true),fxS=makePS(560,false);
function emit(ps,x,y,z,vx,vy,vz,life,s0,s1,r,g,b,a,drag,grav){
let i=ps.n;
if(i>=ps.cap)i=(rnd()*ps.cap)|0;else ps.n++;
ps.x[i]=x;ps.y[i]=y;ps.z[i]=z;ps.vx[i]=vx;ps.vy[i]=vy;ps.vz[i]=vz;
ps.life[i]=life;ps.max[i]=life;ps.s0[i]=s0;ps.s1[i]=s1;ps.r[i]=r;ps.g[i]=g;ps.b[i]=b;ps.a[i]=a;ps.drag[i]=drag;ps.grav[i]=grav;
}
function updPS(ps,dt){
let n=ps.n;
for(let i=0;i<n;){
ps.life[i]-=dt;
if(ps.life[i]<=0){n--;if(i!==n)for(let k=0;k<PF.length;k++){const f=ps[PF[k]];f[i]=f[n];}continue;}
const dr=Math.max(0,1-ps.drag[i]*dt);
ps.vx[i]*=dr;ps.vz[i]*=dr;ps.vy[i]=ps.vy[i]*dr-ps.grav[i]*dt;
ps.x[i]+=ps.vx[i]*dt;ps.y[i]+=ps.vy[i]*dt;ps.z[i]+=ps.vz[i]*dt;
if(ps.y[i]<0.05){ps.y[i]=0.05;ps.vy[i]*= -0.3;}
i++;
}
ps.n=n;
const P=ps.pos,T=ps.tint,S=ps.size;
for(let i=0;i<n;i++){
const f=ps.life[i]/ps.max[i],age=1-f;
P[i*3]=ps.x[i];P[i*3+1]=ps.y[i];P[i*3+2]=ps.z[i];
T[i*4]=ps.r[i];T[i*4+1]=ps.g[i];T[i*4+2]=ps.b[i];
T[i*4+3]=ps.add?ps.a[i]*f:ps.a[i]*Math.min(1,age*6)*f;
S[i]=ps.s0[i]+(ps.s1[i]-ps.s0[i])*age;
}
ps.geo.setDrawRange(0,n);
ps.geo.attributes.position.needsUpdate=true;ps.geo.attributes.tint.needsUpdate=true;ps.geo.attributes.size.needsUpdate=true;
}
function clearPS(ps){ps.n=0;ps.geo.setDrawRange(0,0);}
function updatePointScale(){
const s=view.h*pixelRatio/(2*Math.tan(camera.fov*Math.PI/360));
fxA.mat.uniforms.uScale.value=s;fxS.mat.uniforms.uScale.value=s;
}

