for(let i=0;i<RG.length;i++){RG[i].t=0;hideI(ringIM,i);}
for(let i=14;i<24;i++)hideI(ringIM,i);
for(let i=0;i<BM.length;i++){BM[i].t=0;hideI(beamIM,i);}
