part(L,box(0.8*th+0.25,ls.thigh,1.0*th+0.3,0,-ls.thigh/2,0),P);
part(L,box(0.55*th+0.2,ls.thigh*0.7,0.2,0,-ls.thigh*0.45,0.5*th+0.25),S);
