function archGeo(a){
const g=a.cyl?new THREE.CylinderGeometry(a.r*(a.tap||1),a.r,a.h,14,a.tap?8:4):new THREE.BoxGeometry(a.w,a.h,a.d);
const uv=g.attributes.uv.array,pos=g.attributes.position.array,nor=g.attributes.normal.array,n=g.attributes.position.count,col=new Float32Array(n*3);
for(let i=0;i<n;i++){
const nx=nor[i*3],ny=nor[i*3+1],yy=(pos[i*3+1]+a.h/2)/a.h;
let k;
if(a.cyl){uv[i*2]=0.01;uv[i*2+1]=0.99;k=Math.abs(ny)>0.5?0.6:0.7+0.3*yy;if(a.tap&&yy>0.7&&Math.floor(yy*12)%2===0)k*=0.55;else if(!a.tap&&Math.floor(yy*5)%2===1)k*=0.86;}
else if(Math.abs(ny)>0.5){uv[i*2]=0.01;uv[i*2+1]=0.99;k=0.6;}
else{const fw=Math.abs(nx)>0.5?a.d:a.w;uv[i*2]*=fw/8;uv[i*2+1]*=a.h/8;k=0.7+0.3*yy;}
col[i*3]=k;col[i*3+1]=k;col[i*3+2]=k;
}
g.setAttribute('color',new THREE.BufferAttribute(col,3));
g.translate(0,a.h/2,0);
return keep(g);
}
