let bossMeshes=[]; // [{mesh, key}] rebuilt per boss fight and disposed after
function bossMesh(key,fn,x,y,z){
const g=geoOf(fn);own.pop(); // boss geometry is disposed with the fight, not kept for the whole session
const m=new THREE.Mesh(g,bossMat);m.position.set(x,y,z);bossRoot.add(m);
bossMeshes.push({mesh:m,key:key});
return m;
}
function clearBossMeshes(){
for(let i=0;i<bossMeshes.length;i++){bossRoot.remove(bossMeshes[i].mesh);bossMeshes[i].mesh.geometry.dispose();}
bossMeshes=[];
bossRoot.visible=false;shieldMesh.visible=false;
}
