const idx=nProps,p=props[nProps++],P=PROPS[type];
p.type=type;p.slot=propUsed[type]++;p.x=x;p.y=0;p.z=z;p.ry=ry;p.st=0;p.hp=P.hp;p.t=0;p.burn=0;p.rx=0;p.rz=0;p.sy=1;
p.vx=p.vy=p.vz=0;p.wx=p.wz=0;
tmpC.set(hex);p.cr=tmpC.r;p.cg=tmpC.g;p.cb=tmpC.b;
if(type===PR_BOX){const r90=Math.abs(Math.sin(ry))>0.5,hw=r90?1.2:3,hd=r90?3:1.2;p.x0=x-hw;p.x1=x+hw;p.z0=z-hd;p.z1=z+hd;}
else{p.x0=x-P.r;p.x1=x+P.r;p.z0=z-P.r;p.z1=z+P.r;}
setI(propIM[type],p.slot,x,0,z,ry,1,1,1);colI(propIM[type],p.slot,p.cr,p.cg,p.cb);
