if(ri===0&&x< -125)continue;
if(ri===1){const w=30+r()*60,h=8+r()*22;part(L,box(w,h,w*(0.5+r()*0.6),x,h/2,z),base,0.8+r()*0.3);if(r()<0.15)part(L,cylY(1.5,2,30,6,x,15,z),0x8a7a6a);continue;}
