part(L,box(1.4,34,1.4,x-4,17,z-5),0xb8603a);part(L,box(1.4,34,1.4,x+4,17,z-5),0xb8603a);
part(L,box(1.4,34,1.4,x-4,17,z+5),0xb8603a);part(L,box(1.4,34,1.4,x+4,17,z+5),0xb8603a);
part(L,box(48,2.2,3,x+10,34,z),0xc8703f);part(L,box(6,4,8,x-2,31,z),0x8a4a2a);part(L,box(0.3,14,0.3,x+22,26,z),0x333333);
