if(d<48&&d>30){gx=BS.x-dz/d*10*(Math.sin(BS.t*0.3)>0?1: -1);gz=BS.z+dx/d*10*(Math.sin(BS.t*0.3)>0?1: -1);}else if(d<=30){gx=BS.x-dx/d*10;gz=BS.z-dz/d*10;}
const mv=BS.awake&&phase==='fight'?BS.spd:0,mx=gx-BS.x,mz=gz-BS.z,ml=Math.sqrt(mx*mx+mz*mz)||1;
if(ml>2&&mv>0){BS.yaw=turnTo(BS.yaw,Math.atan2(mx,mz),0.8,dt);BS.x=clamp(BS.x+Math.sin(BS.yaw)*mv*dt,-HALF+8,HALF-8);BS.z=clamp(BS.z+Math.cos(BS.yaw)*mv*dt,-HALF+8,HALF-8);mu.spd=mv;}else mu.spd=0;
mu.legYaw=BS.yaw;mu.x=BS.x;mu.z=BS.z;
