for(let q=0;q<3;q++)emit(fxA,cx,3,cz,Math.sin(BS.yaw)*28+rs()*8,(rnd()-0.2)*4,Math.cos(BS.yaw)*28+rs()*8,0.6,1,4.5,1,0.5,0.1,0.85,2,-2);
damagePlayer(26*dmgMul*dt,PU.x,PU.y+3,PU.z,BS.x,BS.z,true);
