function setRegion(ri){
const R=REGIONS[ri];
paintSky(R.sky[0],R.sky[1],R.sky[2]);
scene.fog.color.setHex(R.fog);scene.fog.near=R.fogN;scene.fog.far=R.fogF;
hemi.color.setHex(R.hemi[0]);hemi.groundColor.setHex(R.hemi[1]);hemi.intensity=R.hemi[2];
sun.color.setHex(R.sun[0]);sun.intensity=R.sun[1];sun.position.set(R.sunDir[0],R.sunDir[1],R.sunDir[2]);
renderer.setClearColor(R.fog);
drawGround(ri);
propIM[PR_TREE].geometry=treeGeos[ri];
water.visible=ri===0;snow.visible=ri===2;
matBld.emissive.setHex(ri===2?0xffd8a0:ri===0?0x6a4a2a:0x000000);
}
const PP={x:0,z:0,yaw:0};
function buildPath(pts){
M.path=pts;M.segL=[0];
let L=0;
for(let i=0;i+1<pts.length;i++){L+=Math.hypot(pts[i+1][0]-pts[i][0],pts[i+1][1]-pts[i][1]);M.segL.push(L);}
M.len=L;
}
function pathAt(s,out){
s=clamp(s,0,M.len);
for(let i=0;i+1<M.path.length;i++){
if(s<=M.segL[i+1]||i+2===M.path.length){
const a=M.path[i],b=M.path[i+1],L=M.segL[i+1]-M.segL[i],t=L>0?clamp((s-M.segL[i])/L,0,1):0;
out.x=a[0]+(b[0]-a[0])*t;out.z=a[1]+(b[1]-a[1])*t;out.yaw=Math.atan2(b[0]-a[0],b[1]-a[1]);
return;
}
}
}
function convoyProg(){return M.len?clamp(M.s/M.len,0,1):0;}
