P.alive=true;P.heat=0;P.spd=0;P.turnV=0;P.vy=0;P.vx=0;P.vz=0;P.dashT=0;P.dashCd=0;P.shutT=0;P.ventT=0;P.ventCd=0;P.kills=0;P.kick=0;
P.stuckT=0;P.stuckX=u.x;P.stuckZ=u.z;P.lockT=0;P.lockU=null;P.locked=false;P.jetMinT=0;P.dmgTaken=0;P.hurtT=0;P.warnT=0;
stats.destr=0;stats.kill=0;stats.obj=0;
M.done=0;M.total=0;M.waveI=0;M.loopT=D.loop?D.loop[0]:0;M.zone=null;M.inZone=false;M.contested=false;M.prog=0;M.need=0;
M.haul.length=0;M.s=0;M.len=0;M.path=null;M.wait=false;M.cmdr=null;M.cmdrEngaged=false;M.cmdrDead=false;M.cmdrPath=[];M.cmdrWP=0;
M.bossDown=false;M.survWave=0;M.survBreak=4;M.siegeT=0;M.tut=D.tut?0: -1;M.tutT=0;M.failMsg='';M.tgtList.length=0;
zoneMesh.visible=false;zoneFill.visible=false;hideI(ringIM,22);ringIM.instanceMatrix.needsUpdate=true;
