const keys={};
let mouseFire=false,tap1=false,tap2=false,stick=null,aimTouch=null,touchAimDX=0,touchAimDY=0,tfire1= -1,tfire2= -1,tjet= -1;
function clearInput(){
for(const k in keys)keys[k]=false;
mouseFire=false;tap1=false;tap2=false;stick=null;aimTouch=null;touchAimDX=0;touchAimDY=0;tfire1= -1;tfire2= -1;tjet= -1;labDrag=null;
}
const USED={KeyW:1,KeyA:1,KeyS:1,KeyD:1,ArrowUp:1,ArrowDown:1,ArrowLeft:1,ArrowRight:1,Space:1,KeyF:1,KeyG:1,ShiftLeft:1,ShiftRight:1,KeyV:1,KeyC:1,KeyP:1,Escape:1,Enter:1,NumpadEnter:1};
function pause(){
if(mode!=='playing'||paused)return;
paused=true;clearInput();audioStop();uiFocus='resume';sfx('ui');
}
function resume(){if(!paused)return;paused=false;lastT=performance.now();acc=0;clearInput();audioStart();sfx('ui');}
function goTitle(scr){
mode='title';paused=false;screen=scr||'menu';
clearUnits();clearProjectiles();clearFX();clearPickups();audioStop();clearInput();
rigs[0].root.visible=false;PU.act=false;
if(screen==='lab')openLab();else uiFocus=screen==='missions'?'m'+nextMission():'start';
}
function tryStart(mi){
if(!misUnlocked(mi)){menuMsg='Locked: finish the earlier missions first.';menuMsgT=2.5;sfx('deny');return;}
const B=budget(curDesign());
if(!B.owned|| !B.ok){ensureDesign();buildPlayerSet();}
startMission(mi);
}
function uiActivate(id){
if(!id)return;
if(paused){
if(id==='resume')resume();
else if(id==='restart'){paused=false;startMission(curMis);}
else if(id==='pshake'){prof.shake= !prof.shake;saveProfile();sfx('select');}
else if(id==='tolab')goTitle('lab');
else if(id==='quit')goTitle('menu');
return;
}
if(mode==='over'){
if(id==='next')startMission(Math.min(11,curMis+1));
else if(id==='retry')startMission(curMis);
else if(id==='olab')goTitle('lab');
else if(id==='omis'){goTitle('missions');uiFocus='m'+curMis;}
return;
}
if(mode!=='title')return;
if(screen==='menu'){
if(id==='start')tryStart(nextMission());
else if(id==='missions'){screen='missions';uiFocus='m'+nextMission();sfx('select');}
else if(id==='lab'){openLab();sfx('select');}
else if(id==='shake'){prof.shake= !prof.shake;saveProfile();sfx('select');}
}else if(screen==='missions'){
if(id==='back'){screen='menu';uiFocus='missions';sfx('ui');}
else if(id.charAt(0)==='m')tryStart(parseInt(id.slice(1),10));
}else if(screen==='lab')labActivate(id);
}
function uiAdjust(dir){
if(mode!=='title'||screen!=='lab'||paused)return false;
if(LAB_ROWS.indexOf(uiFocus)>=0){labAdjust(uiFocus,dir);return true;}
if(uiFocus.charAt(0)==='g'){labActivate(uiFocus);return true;}
return false;
}
function menuKey(c){
if(c==='ArrowUp'||c==='KeyW')uiNav(0,-1);
else if(c==='ArrowDown'||c==='KeyS')uiNav(0,1);
else if(c==='ArrowLeft'||c==='KeyA'){if(!uiAdjust(-1))uiNav(-1,0);}
else if(c==='ArrowRight'||c==='KeyD'){if(!uiAdjust(1))uiNav(1,0);}
else if(c==='Space'||c==='Enter'||c==='NumpadEnter')uiActivate(uiFocus);
}
function onKeyDown(e){
const t=e.target;
if(t&&(t.tagName==='INPUT'||t.tagName==='TEXTAREA'||t.tagName==='SELECT'||t.isContentEditable))return;
const c=e.code;
if(!USED[c])return;
e.preventDefault();
if(mode==='playing'&& !paused){
if(c==='KeyP'||c==='Escape'){if(!e.repeat)pause();return;}
keys[c]=true;
if(e.repeat)return;
if(c==='KeyF')tap1=true;
else if(c==='KeyG')tap2=true;
else if(c==='Space')P.jetMinT=Math.max(P.jetMinT,0.3);
else if(c==='ShiftLeft'||c==='ShiftRight')tryDash();
else if(c==='KeyV')tryVent();
else if(c==='KeyC'){camMode=1-camMode;sfx('ui');}
return;
}
if(e.repeat&&(c==='Space'||c==='Enter'||c==='NumpadEnter'||c==='KeyP'||c==='Escape'))return;
if(paused){if(c==='KeyP'||c==='Escape')resume();else menuKey(c);return;}
if(mode==='over'){if(overT<0.6)return;if(c==='Escape'){goTitle('menu');return;}menuKey(c);return;}
if(c==='Escape'){if(screen==='lab')leaveLab();else if(screen==='missions'){screen='menu';uiFocus='missions';}return;}
menuKey(c);
}
function onKeyUp(e){if(USED[e.code])keys[e.code]=false;}
function onBlur(){if(mode==='playing'&& !paused)pause();clearInput();}
function onVisibility(){if(document.hidden)onBlur();}
function toLogical(cx,cy,ax,ay,out){const s=view.s;out.x=(cx-(view.w-LW*s)*ax)/s;out.y=(cy-(view.h-LH*s)*ay)/s;return out;}
const LG={x:0,y:0};
function capture(e){try{hud.setPointerCapture(e.pointerId);}catch(err){ /* optional */}}
function touchDown(e,cx,cy){
toLogical(cx,cy,1,0,LG);
if(Math.hypot(LG.x-PAUSE_BTN.x,LG.y-PAUSE_BTN.y)<PAUSE_BTN.r+12){pause();return;}
toLogical(cx,cy,1,1,LG);
for(let i=0;i<TBTN.length;i++){
const b=TBTN[i];
if(Math.hypot(LG.x-b.x,LG.y-b.y)>b.r+10)continue;
capture(e);
if(b.id==='f1'){tfire1=e.pointerId;tap1=true;}
else if(b.id==='f2'){tfire2=e.pointerId;tap2=true;}
else if(b.id==='jet'){tjet=e.pointerId;P.jetMinT=Math.max(P.jetMinT,0.3);}
else if(b.id==='dash')tryDash();
else if(b.id==='vent')tryVent();
else if(b.id==='cam')camMode=1-camMode;
return;
}
capture(e);
if(cx<view.w*0.42&& !stick){toLogical(cx,cy,0,1,LG);stick={id:e.pointerId,ox:LG.x,oy:LG.y,vx:0,vy:0};}
else if(!aimTouch)aimTouch={id:e.pointerId,x:cx,y:cy};
}
function onPointerDown(e){
const r=hud.getBoundingClientRect(),cx=e.clientX-r.left,cy=e.clientY-r.top,touch=e.pointerType==='touch';
try{hud.focus({preventScroll:true});}catch(err){ /* older browsers */}
if(touch&& !touchUI)touchUI=true;
if(touch)aimMouse=false; // a finger is not a cursor: stop cursor steering until the mouse moves again
if(e.button!==undefined&&e.button>0&& !touch)return;
ptr.x=cx;ptr.y=cy;ptr.inside=true;
if(mode==='playing'&& !paused){
if(touch||(touchUI&&e.pointerType!=='mouse')){touchDown(e,cx,cy);return;}
if(touchUI){toLogical(cx,cy,1,0,LG);if(Math.hypot(LG.x-PAUSE_BTN.x,LG.y-PAUSE_BTN.y)<PAUSE_BTN.r+12){pause();return;}}
aimMouse=true;mouseFire=true;tap1=true;capture(e);
return;
}
const it=uiAt(cx,cy);
if(paused){if(it){uiFocus=it.id;uiActivate(it.id);}else resume();return;}
if(mode==='over'){if(overT<0.6)return;if(it){uiFocus=it.id;uiActivate(it.id);}return;}
if(!it){if(screen==='lab'){labDrag={id:e.pointerId,x:cx};capture(e);}else if(screen==='menu')tryStart(nextMission());return;} // a click or tap on the title starts the run
if(screen==='lab'&&LAB_ROWS.indexOf(it.id)>=0){
uiFocus=it.id;
const fx=(cx-it.x0)/Math.max(1,it.x1-it.x0);
if(fx<0.42&&fx>0.28)labAdjust(it.id,-1);
else if(fx>0.88)labAdjust(it.id,1);
else if(fx>=0.42&& !rowOwned(it.id))labActivate(it.id);
else if(fx>=0.42)labAdjust(it.id,1);
return;
}
if(screen==='missions'&&it.id.charAt(0)==='m'&&uiFocus!==it.id&&touch){uiFocus=it.id;sfx('ui');return;}
uiFocus=it.id;uiActivate(it.id);
}
function onPointerMove(e){
const r=hud.getBoundingClientRect(),cx=e.clientX-r.left,cy=e.clientY-r.top;
if(e.pointerType==='touch'){
if(stick&&e.pointerId===stick.id){
toLogical(cx,cy,0,1,LG);
let dx=LG.x-stick.ox,dy=LG.y-stick.oy;const d=Math.hypot(dx,dy);
if(d>64){stick.ox=LG.x-dx/d*64;stick.oy=LG.y-dy/d*64;dx=dx/d*64;dy=dy/d*64;}
if(d<7){stick.vx=0;stick.vy=0;}else{stick.vx=clamp(dx/54,-1,1);stick.vy=clamp(-dy/54,-1,1);}
}else if(aimTouch&&e.pointerId===aimTouch.id){touchAimDX+=cx-aimTouch.x;touchAimDY+=cy-aimTouch.y;aimTouch.x=cx;aimTouch.y=cy;}
else if(labDrag&&e.pointerId===labDrag.id){labSpin+=(cx-labDrag.x)*0.012;labDrag.x=cx;}
return;
}
const moved=Math.abs(cx-ptr.x)+Math.abs(cy-ptr.y)>1;
ptr.x=cx;ptr.y=cy;ptr.inside=true;
if(labDrag&&e.pointerId===labDrag.id){labSpin+=(cx-labDrag.x)*0.012;labDrag.x=cx;return;}
if(mode==='playing'&& !paused){if(moved)aimMouse=true;return;}
if(moved){const it=uiAt(cx,cy);if(it&&it.id!==uiFocus)uiFocus=it.id;}
}
function onPointerUp(e){
if(stick&&e.pointerId===stick.id)stick=null;
if(aimTouch&&e.pointerId===aimTouch.id)aimTouch=null;
if(tfire1===e.pointerId)tfire1= -1;
if(tfire2===e.pointerId)tfire2= -1;
if(tjet===e.pointerId)tjet= -1;
if(labDrag&&labDrag.id===e.pointerId)labDrag=null;
if(e.pointerType!=='touch')mouseFire=false;
}
function onPointerLeave(e){if(e.pointerType!=='touch'){ptr.inside=false;mouseFire=false;}}
function onContextMenu(e){e.preventDefault();}
let cursorNow='';
function updateCursor(){
const want=mode==='playing'&& !paused&&aimMouse&&P.alive?'none':'default';
if(want!==cursorNow){cursorNow=want;hud.style.cursor=want;}
}

