function inst(geo, mat, cap, colorize, order) {
const m = new THREE.InstancedMesh(geo, mat, cap);
m.frustumCulled = false;
if (THREE.DynamicDrawUsage && m.instanceMatrix.setUsage) m.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
if (colorize) { tmpC.setRGB(1, 1, 1); for (let i = 0; i < cap; i++) m.setColorAt(i, tmpC); }
m.count = 0; m.visible = false;
if (order) m.renderOrder = order;
scene.add(m);
return m;
}
function putY(m, k, x, y, z, yaw, sx, sy, sz) { // fast matrix write: rotation about y + scale
const a = m.instanceMatrix.array, o = k * 16, c = Math.cos(yaw), s = Math.sin(yaw);
a[o] = c * sx; a[o + 1] = 0; a[o + 2] = -s * sx; a[o + 3] = 0;
a[o + 4] = 0; a[o + 5] = sy; a[o + 6] = 0; a[o + 7] = 0;
a[o + 8] = s * sz; a[o + 9] = 0; a[o + 10] = c * sz; a[o + 11] = 0;
a[o + 12] = x; a[o + 13] = y; a[o + 14] = z; a[o + 15] = 1;
}
function putM(m, k) { dummy.updateMatrix(); dummy.matrix.toArray(m.instanceMatrix.array, k * 16); }
function putC(m, k, r, g, b) { const a = m.instanceColor.array, o = k * 3; a[o] = r; a[o + 1] = g; a[o + 2] = b; }
function finish(m, n) { // upload only the live slots, not the whole capacity, every frame
m.count = n; m.visible = n > 0;
if (n > 0) {
const im = m.instanceMatrix; im.updateRange.offset = 0; im.updateRange.count = n * 16; im.needsUpdate = true;
const ic = m.instanceColor; if (ic) { ic.updateRange.offset = 0; ic.updateRange.count = n * 3; ic.needsUpdate = true; }
}
}
