const PV = [
'attribute float size;',
'attribute vec4 rgba;',
'uniform float uScale;',
'varying vec4 vC;',
'void main() {',
'  vC = rgba;',
'  vec4 mv = modelViewMatrix * vec4(position, 1.0);',
'  gl_PointSize = clamp(size * uScale / max(0.5, -mv.z), 1.0, 128.0);',
'  gl_Position = projectionMatrix * mv;',
'}',
].join('\n');
const PF = [
'varying vec4 vC;',
'void main() {',
'  vec2 p = gl_PointCoord - vec2(0.5);',
'  float d = dot(p, p);',
'  if (d > 0.25) discard;',
'  gl_FragColor = vec4(vC.rgb, vC.a * (1.0 - d * 4.0));',
'}',
].join('\n');
const PS_FIELDS = ['x', 'y', 'z', 'vx', 'vy', 'vz', 'life', 'max', 's0', 's1', 'r', 'g', 'b', 'a', 'drag', 'grav'];
function makePS(cap, additive) {
const geo = keep(new THREE.BufferGeometry());
const pos = new Float32Array(cap * 3), size = new Float32Array(cap), rgba = new Float32Array(cap * 4);
geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
geo.setAttribute('size', new THREE.BufferAttribute(size, 1));
geo.setAttribute('rgba', new THREE.BufferAttribute(rgba, 4));
geo.setDrawRange(0, 0);
const mat = keep(new THREE.ShaderMaterial({
uniforms: { uScale: { value: 500 } }, vertexShader: PV, fragmentShader: PF,
transparent: true, depthWrite: false, blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
}));
const pts = new THREE.Points(geo, mat);
pts.frustumCulled = false; pts.renderOrder = additive ? 8 : 7;
scene.add(pts);
const S = { cap: cap, n: 0, geo: geo, pos: pos, size: size, rgba: rgba, mat: mat };
for (let k = 0; k < PS_FIELDS.length; k++) S[PS_FIELDS[k]] = new Float32Array(cap);
return S;
}
const fxAdd = makePS(MAX_ADD, true), fxSmk = makePS(MAX_SMK, false);
function emit(S, x, y, z, vx, vy, vz, life, s0, s1, hex, a, drag, grav) {
let i = S.n;
if (i >= S.cap) i = (Math.random() * S.cap) | 0; else S.n++;
S.x[i] = x; S.y[i] = y; S.z[i] = z; S.vx[i] = vx; S.vy[i] = vy; S.vz[i] = vz;
S.life[i] = life; S.max[i] = life; S.s0[i] = s0; S.s1[i] = s1;
tmpC.set(hex); S.r[i] = tmpC.r; S.g[i] = tmpC.g; S.b[i] = tmpC.b;
S.a[i] = a; S.drag[i] = drag; S.grav[i] = grav;
}
function updPS(S, dt) {
let n = S.n;
const pos = S.pos, size = S.size, rgba = S.rgba;
for (let i = 0; i < n;) {
const l = S.life[i] - dt;
if (l <= 0) {
n--;
if (i !== n) for (let k = 0; k < PS_FIELDS.length; k++) { const arr = S[PS_FIELDS[k]]; arr[i] = arr[n]; }
continue;
}
S.life[i] = l;
const kd = Math.max(0, 1 - S.drag[i] * dt);
S.vx[i] *= kd; S.vz[i] *= kd; S.vy[i] = S.vy[i] * kd - S.grav[i] * dt;
S.x[i] += S.vx[i] * dt; S.y[i] += S.vy[i] * dt; S.z[i] += S.vz[i] * dt;
if (S.y[i] < 0.05) { S.y[i] = 0.05; if (S.vy[i] < 0) S.vy[i] *= -0.3; S.vx[i] *= 0.7; S.vz[i] *= 0.7; }
const t = 1 - l / S.max[i];
pos[i * 3] = S.x[i]; pos[i * 3 + 1] = S.y[i]; pos[i * 3 + 2] = S.z[i];
size[i] = S.s0[i] + (S.s1[i] - S.s0[i]) * t;
rgba[i * 4] = S.r[i]; rgba[i * 4 + 1] = S.g[i]; rgba[i * 4 + 2] = S.b[i];
rgba[i * 4 + 3] = S.a[i] * Math.min(1, t * 8) * (1 - t);
i++;
}
S.n = n;
S.geo.setDrawRange(0, n);
if (n > 0) {
S.geo.attributes.position.needsUpdate = true;
S.geo.attributes.size.needsUpdate = true;
S.geo.attributes.rgba.needsUpdate = true;
}
}

