let sx = 0, sz = 0;
if (dt > 0) {
if (shake > 0 && !reduceMotion) { sx = rand(-1, 1) * shake * 0.6; sz = rand(-1, 1) * shake * 0.6; }
shake = Math.max(0, shake - dt * 2.2);
}
camera.position.set(cam.x + sx, 23 * cam.zoom, cam.z + 14 * cam.zoom + sz);
