if (dt > 0) dark += clamp(t - dark, -dt * 0.4, dt * 0.4);
if (Math.abs(dark - lastDark) < 0.002) return;
lastDark = dark;
hemi.color.copy(DAY_SKY).lerp(NIGHT_SKY, dark);
hemi.groundColor.copy(DAY_GND).lerp(NIGHT_GND, dark);
