const m = 34;
if (scr.ok && scr.x > m && scr.x < view.w - m && scr.y > m && scr.y < view.h - m) return;
const cxs = view.w / 2, cys = view.h / 2;
let dx = scr.x - cxs, dy = scr.y - cys;
if (!scr.ok) { dx = -dx; dy = -dy; }
const sc = Math.min((view.w / 2 - m) / Math.max(1e-3, Math.abs(dx)), (view.h / 2 - m) / Math.max(1e-3, Math.abs(dy)));
