ctx.shadowColor = 'rgba(0, 0, 0, 0.7)'; ctx.shadowBlur = 10;
txt(ctx, banner.text, 480, 196, 40, FONT_D, banner.col, 'center', 860);
ctx.shadowBlur = 0;
