function hintText() {
if (mode !== 'playing' || phase !== 'day' || techOpen || dayNum > 2) return '';
if (!gatheredOnce) return touchUI ? 'Shoot crystals and wrecks, or stand next to them, to gather' : 'Shoot crystals and wrecks (or stand next to them) to gather resources';
if (!builtTurret) return touchUI ? 'Tap BUILD, pick the autogun (2) and tap near the core' : 'Press 2 for an autogun, then click near the core to build it';
if (!builtWall) return touchUI ? 'Walls (1) funnel bugs. Drag to paint a line' : 'Walls (1) funnel the bugs. Click-drag to paint a line, build on a wall to upgrade';
if (dayNum === 1) return touchUI ? 'Turrets need a power ring. Tap the timer to start the night' : 'Turrets only fire inside a power ring. Press Space twice to start the night';
return '';
}

