if (e.pointerId === touch.shootId) { touch.shootId = -1; if (mode === 'playing' && !paused) { inp.shootUp = true; inp.upX = evExtra(); } }
if (e.pointerId === touch.sprintId) { touch.sprintId = -1; touch.sprint = false; }
