function boxRect(x0, y0, x1, y1, col) {
const a = project(x0, y0, 0), ax = a.x, ay = a.y, b = project(x1, y1, 0);
ctx.strokeStyle = col; ctx.lineWidth = 2;
ctx.strokeRect(Math.min(ax, b.x), Math.min(ay, b.y), Math.abs(b.x - ax), Math.abs(b.y - ay));
}
function drawBoxes() {
devSpace();
for (let i = 0; i < 2; i++) {
const f = F[i];
const h = hurtMain(f, HB1);
boxRect(h.x0, h.y0, h.x1, h.y1, 'rgba(75, 227, 160, 0.9)');
const e = hurtExt(f, HB2);
if (e) boxRect(e.x0, e.y0, e.x1, e.y1, 'rgba(75, 227, 160, 0.5)');
if (f.st === 'atk' && f.m.hb && f.mf >= f.m.st && f.mf < f.m.st + f.m.ac) {
const m = f.m, sz = f.C.sz, cx = f.x + f.facing * m.hb[0] * sz, cy = f.y + m.hb[1] * sz, w = m.hb[2] * sz, hh = m.hb[3] * sz;
boxRect(cx - w / 2, Math.max(0, cy - hh / 2), cx + w / 2, cy + hh / 2, m.kind === 't' || m.grab ? 'rgba(255, 201, 60, 0.95)' : 'rgba(255, 93, 93, 0.95)');
}
}
for (let i = 0; i < PROJ_MAX; i++) {
const P = projs[i];
if (!P.on || P.delay > 0) continue;
projBox(P, BX);
boxRect(BX.x0, BX.y0, BX.x1, BX.y1, 'rgba(255, 93, 93, 0.95)');
}
}
