function emblem(cx, cy, s, C, locked) {
const c0 = locked ? '#2a2f3a' : hexCss(C.col[0]), c1 = locked ? '#3a404c' : hexCss(C.col[1]), c2 = locked ? '#1a1e26' : hexCss(C.col[2]), g = locked ? '#55606e' : hexCss(C.col[3]);
ctx.fillStyle = c1;
ctx.beginPath(); ctx.moveTo(cx - 26 * s, cy + 16 * s); ctx.lineTo(cx - 20 * s, cy - 2 * s); ctx.lineTo(cx + 20 * s, cy - 2 * s); ctx.lineTo(cx + 26 * s, cy + 16 * s); ctx.closePath(); ctx.fill();
ctx.fillStyle = c0; ctx.fillRect(cx - 14 * s, cy - 4 * s, 28 * s, 20 * s);
const hd = C.body.head;
ctx.fillStyle = hd === 'dome' ? c2 : c0;
if (hd === 'dome') { ctx.beginPath(); ctx.arc(cx, cy - 10 * s, 12 * s, Math.PI, 0); ctx.fill(); }
else ctx.fillRect(cx - 10 * s, cy - 22 * s, 20 * s, 16 * s);
ctx.fillStyle = c1;
if (hd === 'horn' || hd === 'crown') { for (let k = -1; k <= 1; k += hd === 'horn' ? 2 : 1) { ctx.beginPath(); ctx.moveTo(cx + k * 6 * s - 3 * s, cy - 22 * s); ctx.lineTo(cx + k * 9 * s, cy - 34 * s); ctx.lineTo(cx + k * 6 * s + 3 * s, cy - 22 * s); ctx.fill(); } }
if (hd === 'crest') { ctx.beginPath(); ctx.moveTo(cx - 3 * s, cy - 22 * s); ctx.lineTo(cx, cy - 36 * s); ctx.lineTo(cx + 3 * s, cy - 22 * s); ctx.fill(); }
ctx.fillStyle = g;
if (hd === 'mono') { ctx.beginPath(); ctx.arc(cx, cy - 14 * s, 4 * s, 0, TAU); ctx.fill(); }
else ctx.fillRect(cx - 8 * s, cy - 16 * s, 16 * s, 4 * s);
}
function wrapLines(s, maxW, size, family) {
ctx.font = font(size, family);
const words = s.split(' '), out = [];
let line = '';
for (let i = 0; i < words.length; i++) {
const t = line ? line + ' ' + words[i] : words[i];
if (ctx.measureText(t).width > maxW && line) { out.push(line); line = words[i]; } else line = t;
}
if (line) out.push(line);
return out;
}
