function drawTags() { // nickname tags over the mechs
const N = net;
if (!N) return;
devSpace();
const s = Math.max(0.7, view.s), sz = Math.round(12 * s);
if (N.tagSz !== sz) { // measure the two names again only when the size changes
N.tagSz = sz; ctx.font = font(sz, FONT_M, '700');
N.tagW[0] = ctx.measureText(N.names[0]).width; N.tagW[1] = ctx.measureText(N.names[1]).width;
}
for (let i = 0; i < 2; i++) {
const f = F[i];
if (f.hidden) continue;
const p = project(f.x + visX[i], f.y + 3.5 * f.C.sz, 0);
if (!p.ok) continue;
const own = i === (N.host ? 0 : 1);
const w = N.tagW[i] + 14 * s;
pill(p.x - w / 2, p.y - 10 * s, w, 20 * s, 'rgba(8, 12, 22, 0.6)', own ? UI.hi : null);
txt(ctx, N.names[i], p.x, p.y + 1, sz, FONT_M, own ? UI.hi : '#FFFFFF', 'center', 0, '700');
}
}
