const wheelPos = new THREE.Vector3(), mLocal = new THREE.Matrix4(), mRot = new THREE.Matrix4(), mOut = new THREE.Matrix4();
const FLAME_HEX = [0xff8a2a,0xffe14a,0xff5a2a,0x5af0ff,0xfff0a0,0xffe080,0xff6a2a];
function setKartColors() {
for (let i = 0; i < karts.length; i++) {
const k = karts[i];
tmpC.setHex(WHEELS[k.wi].col); for (let w = 0; w < 4; w++) wheelIM.setColorAt(k.mi * 4 + w, tmpC);
tmpC.setHex(k.col); for (let c = 0; c < 3; c++) cellIM.setColorAt(k.mi * 3 + c, tmpC);
}
wheelIM.instanceColor.needsUpdate = true; cellIM.instanceColor.needsUpdate = true;
}
function updKartVisuals(dt) {
let nb = 0, nf = 0, np = 0, nl = 0;
const bp = beamGeo.attributes.position.array, bat = R && R.mode === 'battle';
for (let i = 0; i < karts.length; i++) {
const k = karts[i], km = kartMeshes[k.mi], g = km.g, m = km.m;
if (k.out) { g.visible = false; for (let w = 0; w < 4; w++) wheelIM.setMatrixAt(k.mi * 4 + w, ZERO_M); for (let c = 0; c < 3; c++) cellIM.setMatrixAt(k.mi * 3 + c, ZERO_M); continue; }
g.visible = !(k.respT > 0 && floor(clock * 14) % 2 === 0);
const sp = abs(k.vF), fx = sin(k.yaw), fz = cos(k.yaw);
if (k.trick) k.trickR = min(TAU, k.trickR + dt * 13);
const yawV = k.yaw + k.spinA - k.drift * .28;
const pt = k.onG ? -atan2(k.vy, max(6, sp)) : clamp(-k.vy * .03,-.35,.35);
k.pitch += (pt - k.pitch) * min(1, dt * 10);
k.roll += (-k.steerS * .05 * clamp(sp / 20,0,1) - k.drift * .09 - k.roll) * min(1, dt * 8);
let rx = k.pitch, rz = k.roll;
if (k.flipT > 0) { if (k.flipAx) rz += k.flipA; else rx -= k.flipA; }
if (k.trick) rz += k.trickR * (k.di % 2 ? 1 : -1);
k.bob = k.onG ? sin(clock * 34 + i) * .012 * clamp(sp / 10,0,1) : 0;
g.position.set(k.x, k.y + k.bob + (k.flipT > 0 ? .4 : 0), k.z);
g.rotation.set(rx, yawV, rz);
const sq = k.squashT > 0 ? .32 : 1;
m.scale.y += (sq - m.scale.y) * min(1, dt * (sq < 1 ? 30 : 6));
m.scale.x = m.scale.z = 1 + (1 - m.scale.y) * .35;
g.updateMatrixWorld(true);
const W = WHEELS[k.wi], wr = W.r, ww = W.w, sy = m.scale.y;
k.wheelSpin += k.vF / wr * dt;
const steerA = k.drift !== 0 ? -k.drift * .25 : -k.steerS * .42;
for (let w = 0; w < 4; w++) {
mLocal.makeRotationX(k.wheelSpin);
if (w < 2) { mRot.makeRotationY(steerA); mLocal.premultiply(mRot); }
mRot.makeScale(ww, wr * sy, wr); mLocal.multiply(mRot);
mLocal.setPosition((w % 2 ? 1 : -1) * (.72 + ww * .5), wr * sy, w < 2 ? .82 : -.8);
mOut.multiplyMatrices(g.matrixWorld, mLocal);
wheelIM.setMatrixAt(k.mi * 4 + w, mOut);
}
const gy = k.lastGy, ss = 1 / (1 + max(0, k.y - gy) * .25);
dummy.position.set(k.x, gy + .05, k.z); dummy.rotation.set(0, k.yaw + k.spinA, 0); dummy.scale.set(2.5 * ss, 1,3.3 * ss); dummy.updateMatrix();
blobIM.setMatrixAt(nb++, dummy.matrix);
if (k.boostT > 0) {
const fl = .7 + k.boostK * .55 + random() * .35, fh = FLAME_HEX[k.boostC] || FLAME_HEX[0];
tmpC.setHex(fh);
for (let s = -1; s <= 1; s += 2) {
wheelPos.set(s * .3,.72,-1.22).applyMatrix4(g.matrixWorld);
dummy.position.copy(wheelPos); dummy.rotation.set(rx, yawV, rz); dummy.scale.set(1,1, fl); dummy.updateMatrix();
flameIM.setMatrixAt(nf, dummy.matrix); flameIM.setColorAt(nf, tmpC); nf++;
}
if (dt > 0 && random() < dt * 30) emit(PSP, wheelPos.x, wheelPos.y, wheelPos.z, -fx * 6,1, -fz * 6,.25, fh, .7,.1,0,2);
}
if (dt > 0) {
if (k.drift !== 0 && k.onG) {
const hex = STAGE_HEX[k.dStage], n = k.dStage ? 2 : 1;
for (let s = -1; s <= 1; s += 2) {
if (random() > dt * 40 * n) continue;
wheelPos.set(s * .8,.1,-.85).applyMatrix4(g.matrixWorld);
emit(PSP, wheelPos.x, wheelPos.y, wheelPos.z, (random() - .5) * 5 - fx * 4,1.5 + random() * 3, (random() - .5) * 5 - fz * 4,.32, hex, k.dStage ? .45 : .25,.05,14,1);
}
if (random() < dt * 10) emit(PSM, k.x - fx * 1.2, k.y + .25, k.z - fz * 1.2,0,.6,0,.7, WD && WD.theme === 2 ? 0xe8f0ff : 0x9a9aa0,.6,1.8,-.4,1.5,.45);
}
if (k.kind === 1 && k.onG && sp > 8 && random() < dt * 14) emit(PSM, k.x, k.y + .3, k.z, 0,1,0,.7, dustCol(), .8,2,-.5,1,.6);
if (k.staticT > 0 && random() < dt * 20) emit(PSP, k.x + (random() - .5) * 1.6, k.y + .6 + random(), k.z + (random() - .5) * 1.6,0,1,0,.2,0x7dff9a,.35,.05,0,0);
if (k.tarT > 0 && random() < dt * 8) emit(PSM, k.x, k.y + .5, k.z, 0,-1,0,.6,0x241a3a,.5,.3,4,0);
}
if (k.shT > 0) for (let p = 0; p < 5 && np < KMAX * 5; p++) {
const a = clock * 3 + p / 5 * TAU;
dummy.position.set(k.x + sin(a) * 1.75, k.y + .9 + sin(clock * 4 + p) * .15, k.z + cos(a) * 1.75);
dummy.rotation.set(0, a, .3); dummy.scale.setScalar(k.shT < 2 && floor(clock * 10) % 2 === 0 ? .6 : 1); dummy.updateMatrix();
plateIM.setMatrixAt(np++, dummy.matrix);
}
if (bat) for (let c = 0; c < 3; c++) {
if (c >= k.cells) { cellIM.setMatrixAt(k.mi * 3 + c, ZERO_M); continue; }
const a = clock * 2 + c / 3 * TAU;
dummy.position.set(k.x + sin(a) * .7, k.y + 2.3, k.z + cos(a) * .7); dummy.rotation.set(clock, clock * 1.3,0); dummy.scale.setScalar(1.1); dummy.updateMatrix();
cellIM.setMatrixAt(k.mi * 3 + c, dummy.matrix);
}
if (k.magT > 0 && k.magTgt && nl < KMAX) {
const o = nl++ * 6, t = k.magTgt;
bp[o] = k.x; bp[o + 1] = k.y + 1; bp[o + 2] = k.z; bp[o + 3] = t.x; bp[o + 4] = t.y + 1; bp[o + 5] = t.z;
}
}
ghostG.visible = false;
if (ghost && R && R.mode === 'tt' && (R.phase === 'race' || R.phase === 'done') && state === 'playing') {
const f = R.raceT * 10, i0 = floor(f);
if (i0 < ghost.n - 1) {
const t = f - i0, a = ghost.d, o = i0 * 4;
ghostG.position.set(lerp(a[o], a[o + 4], t), lerp(a[o + 1], a[o + 5], t), lerp(a[o + 2], a[o + 6], t));
ghostG.rotation.set(0, a[o + 3] + wrapA(a[o + 7] - a[o + 3]) * t, 0);
ghostG.visible = true;
}
}
blobIM.count = nb; blobIM.instanceMatrix.needsUpdate = true;
flameIM.count = nf; flameIM.instanceMatrix.needsUpdate = true; if (nf) flameIM.instanceColor.needsUpdate = true;
plateIM.count = np; plateIM.instanceMatrix.needsUpdate = true;
cellIM.count = bat ? KMAX * 3 : 0; cellIM.instanceMatrix.needsUpdate = true;
wheelIM.instanceMatrix.needsUpdate = true;
beamGeo.setDrawRange(0, nl * 2); if (nl) beamGeo.attributes.position.needsUpdate = true;
}

