ctx.fillStyle = 'rgba(120, 88, 40, 0.35)';
for (let i = 0; i < 12; i++) { ctx.save(); ctx.translate(gx, gy); ctx.rotate(i / 12 * TAU + 0.1); ctx.fillRect(-gr * 0.12, -gr * 1.18, gr * 0.24, gr * 0.3); ctx.restore(); }
ctx.beginPath(); ctx.arc(gx, gy, gr, 0, TAU); ctx.fill();
ctx.fillStyle = 'rgba(30, 20, 10, 0.6)'; ctx.beginPath(); ctx.arc(gx, gy, gr * 0.3, 0, TAU); ctx.fill();
const fy = h * 0.8;
const fg = ctx.createLinearGradient(0, fy, 0, h);
fg.addColorStop(0, '#8a5a32'); fg.addColorStop(0.18, '#6a4428'); fg.addColorStop(1, '#3a2414');
ctx.fillStyle = fg; ctx.fillRect(0, fy, w, h - fy);
ctx.fillStyle = '#d9a64c'; ctx.fillRect(0, fy - 2, w, 3);
ctx.strokeStyle = 'rgba(40, 24, 12, 0.5)'; ctx.lineWidth = 1;
for (let i = 0; i < 5; i++) { ctx.beginPath(); ctx.moveTo(0, fy + 10 + i * 9); ctx.bezierCurveTo(w * 0.3, fy + 6 + i * 9, w * 0.6, fy + 14 + i * 9, w, fy + 8 + i * 9); ctx.stroke(); }
ctx.save(); ctx.translate(w * 0.16, h * 0.5); ctx.rotate(0.42);
ctx.fillStyle = '#b07a42'; ctx.fillRect(-w * 0.13, -5, w * 0.26, 10);
ctx.fillStyle = '#e2b15a'; ctx.fillRect(-w * 0.13 - 3, -6, 5, 12); ctx.fillRect(w * 0.13 - 2, -6, 5, 12);
ctx.restore();
ctx.fillStyle = '#5b6571'; ctx.fillRect(w * 0.27, h * 0.56, 6, fy - h * 0.56);
const bx = w * 0.3, by = h * 0.62, br = h * 0.055;
ctx.strokeStyle = 'rgba(255, 220, 170, 0.35)'; ctx.lineWidth = 2;
for (let i = 1; i <= 3; i++) { ctx.beginPath(); ctx.moveTo(bx - br - i * 9, by - i * 5 - 2); ctx.lineTo(bx - br - i * 9 - 16, by - i * 5 - 9); ctx.stroke(); }
ctx.beginPath(); ctx.arc(bx, by, br, 0, TAU); ctx.fillStyle = '#d8463a'; ctx.fill();
ctx.beginPath(); ctx.moveTo(bx, by); ctx.arc(bx, by, br, 0.4, 1.2); ctx.closePath(); ctx.fillStyle = '#f1e2c4'; ctx.fill();
ctx.beginPath(); ctx.moveTo(bx, by); ctx.arc(bx, by, br, 3.5, 4.3); ctx.closePath(); ctx.fill();
ctx.beginPath(); ctx.arc(bx - br * 0.35, by - br * 0.4, br * 0.28, 0, TAU); ctx.fillStyle = 'rgba(255, 255, 255, 0.35)'; ctx.fill();
const angs = [1.05, 0.9, 0.7, 0.45, 0.2, 0.04, 0];
const dh = h * 0.26, dw = dh * 0.2;
for (let i = 0; i < angs.length; i++) {
const x = w * 0.38 + i * w * 0.062;
ctx.save(); ctx.translate(x + dw / 2, fy); ctx.rotate(angs[i]);
ctx.fillStyle = '#1e2026'; ctx.fillRect(-dw, -dh, dw, dh);
ctx.strokeStyle = '#e8b65e'; ctx.lineWidth = 1.5; ctx.strokeRect(-dw, -dh, dw, dh);
ctx.fillStyle = '#e8b65e'; ctx.fillRect(-dw + 2, -dh / 2 - 1, dw - 4, 2);
ctx.beginPath(); ctx.arc(-dw / 2, -dh * 0.75, 2.2, 0, TAU); ctx.arc(-dw / 2, -dh * 0.25, 2.2, 0, TAU); ctx.fill();
ctx.restore();
}
const ex = w * 0.86, ey = fy;
ctx.fillStyle = '#5a3a24'; ctx.fillRect(ex - 4, ey - h * 0.2, 8, h * 0.2);
const bell = ctx.createLinearGradient(ex - 30, 0, ex + 30, 0);
bell.addColorStop(0, '#9c7330'); bell.addColorStop(0.45, '#ffd77a'); bell.addColorStop(1, '#b8862e');
ctx.fillStyle = bell;
ctx.beginPath(); ctx.moveTo(ex - h * 0.1, ey - h * 0.2); ctx.quadraticCurveTo(ex - h * 0.09, ey - h * 0.42, ex, ey - h * 0.42); ctx.quadraticCurveTo(ex + h * 0.09, ey - h * 0.42, ex + h * 0.1, ey - h * 0.2); ctx.closePath(); ctx.fill();
ctx.fillStyle = '#ffe9a8'; ctx.fillRect(ex - h * 0.105, ey - h * 0.215, h * 0.21, 4);
const ring = ctx.createRadialGradient(ex, ey - h * 0.3, 2, ex, ey - h * 0.3, h * 0.32);
