const s = snd;
snd = null;
for (let i = 0; i < s.srcs.length; i++) { try { s.srcs[i].stop(); } catch (err) { /* already stopped */ } }
for (let i = 0; i < s.nodes.length; i++) { try { s.nodes[i].disconnect(); } catch (err) { /* already disconnected */ } }
