if (e.repeat) return;
if (c === 'KeyP' || c === 'Escape') pause();
else if (c === 'Space') act.stomp = true;
else if (c === 'KeyJ') act.punch = true;
else if (c === 'ShiftLeft' || c === 'ShiftRight') act.charge = true;
else if (c === 'KeyE') act.grab = true;
else if (c === 'KeyQ') act.rage = true;
