ctx.fillStyle = 'rgba(0,0,0,0.32)';
const so = scroll % 36;
for (let y = so - 36; y < H; y += 36) ctx.fillRect(148, y, 50, 2);
ctx.fillStyle = '#4b5470'; ctx.fillRect(198, 0, 5, H);
ctx.fillStyle = '#0f131e'; ctx.fillRect(203, 0, 67, H);
