ctx.fillStyle = 'rgba(255,201,60,0.85)'; ctx.fillRect(ROAD_X + 4, 0, 4, H);
ctx.fillStyle = 'rgba(235,240,255,0.8)'; ctx.fillRect(ROAD_X + ROAD_W - 8, 0, 4, H);
