const lines = [];
for (let i = 0; i < 14; i++) lines.push({ x: ROAD_X + 20 + hash(i * 3.1) * (ROAD_W - 40), y: hash(i * 7.7) * 520, len: 50 + hash(i) * 70, a: 0.18 });
