if (k === 'ArrowRight' || c === 'KeyD' || k === 'd' || k === 'D') return 'right';
if (k === 'ArrowUp' || c === 'KeyW' || k === 'w' || k === 'W') return 'up';
if (k === 'ArrowDown' || c === 'KeyS' || k === 's' || k === 'S') return 'down';
if (k === ' ' || k === 'Spacebar' || c === 'Space' || k === 'Enter' || c === 'NumpadEnter') return 'start';
if (k === 'p' || k === 'P' || c === 'KeyP' || k === 'Escape' || k === 'Esc') return 'pause';
