for (let i = 0; i < g.vehicles.length; i++) {
const v = g.vehicles[i];
if (v.y - v.h / 2 < 200) for (let l = 0; l < LANES; l++) if (inLane(v, l)) blocked[l] = true;
}
for (let i = 0; i < g.cones.length; i++) if (g.cones[i].y < 170) blocked[g.cones[i].lane] = true;
