if (!open.length) return false;
const gap = open[Math.floor(Math.random() * open.length)];
const cands = shuffle(closable.filter(function (l) { return l !== gap; }));
const n = Math.min(cands.length, g.t > 110 ? 3 : 2);
if (n < 1) return false;
for (let i = 0; i < n; i++) {
const l = cands[i];
g.cones.push({ lane: l, x: laneX(l) - 26, y: -30, flash: true, dead: false });
g.cones.push({ lane: l, x: laneX(l) + 26, y: -30, flash: false, dead: false });
}
g.reserveLane = gap; g.reserveT = 2.4;
