popup(g.x, PLAYER_Y - 64, 'NEAR MISS +50', C_HI);
api.noise(0.22, { vol: 0.14, filter: 2200 });
api.tone(820, 0.16, { type: 'sine', vol: 0.06, slide: 360 });
