g.spin = side * rand(3, 5); g.vx = side * rand(60, 140);
if (v) { v.wrecked = true; v.v = 0; v.spin = -side * rand(2, 4); v.vx = -side * rand(40, 100); v.sig = 0; v.ch = false; v.sigT = 0; }
if (cone) cone.dead = true;
burst(hx, hy, 46, FIRE, 420, 'fire', 0.7, 7);
burst(hx, hy, 34, C_HI_RGB, 560, 'spark', 0.6, 2);
burst(hx, hy, 18, WHITE, 120, 'smoke', 1.6, 9);
if (cone) burst(cone.x, cone.y, 12, [255, 138, 42], 300, 'spark', 0.6, 3);
api.noise(0.7, { vol: 0.45, filter: 700 });
