ctx.setLineDash([10, 10]); ctx.strokeStyle = 'rgba(255,255,255,0.4)'; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(ROAD_X, BOOST_ZONE_Y); ctx.lineTo(ROAD_X + ROAD_W, BOOST_ZONE_Y); ctx.stroke();
ctx.setLineDash([]);
ctx.strokeStyle = C_HI; ctx.lineWidth = 4; arrow(W / 2, 150, 0);
ctx.fillStyle = C_HEAD; ctx.textAlign = 'center'; ctx.font = '600 15px ' + FONT_BODY;
ctx.fillText('Hold up here or swipe up to boost', W / 2, 186, ROAD_W - 20);
