for (let i = 0; i < POPS.length; i++) if (POPS[i].t <= 0) { p = POPS[i]; break; }
if (p.t > 0) { let o = POPS[0]; for (let i = 1; i < POPS.length; i++) if (POPS[i].t < o.t) o = POPS[i]; p = o; }
for (let i = 0; i < POPS.length; i++) if (POPS[i].t > 0) POPS[i].lift = (POPS[i].lift || 0) + 1;
p.text = text; p.sub = sub || ''; p.col = col || UI.head; p.size = size || 30; p.life = 1.6; p.t = 1.6; p.lift = 0;
