const prox = gap < 1.6 ? 1 + (1.6 - Math.max(0, gap)) / 1.6 : 1;
D.prox = prox - 1;
const rate = (Math.min(ang, 70) - 8) * P.spd * 0.6 * (1 + Math.min(D.held, 5) * 0.12) * prox;
const pts = Math.max(0, rate) * dt;
