D.drifting = false; D.lastHeld = D.held; D.prox = 0;
if (D.held > 4) { D.chain += 400 * D.mult; popup('LONG SLIDE', '+' + fmtNum(400 * D.mult), UI.hi, 24); }
if (D.maxAng > 52 && D.held > 0.8) { D.chain += 300 * D.mult; popup('WIDE ANGLE', '+' + fmtNum(300 * D.mult), UI.pink, 24); }
