const drift = touch ? 'tap H-BRAKE' : 'tap SPACE', rk = touch ? 'Tap RESET' : 'Press R';
TIP.gas = (touch ? 'Hold GAS' : 'Hold W') + ' to pick up speed';
TIP.corner = 'Ease off or ' + (touch ? 'tap BRAKE' : 'tap S') + ' before the corner, then steer in and ' + drift + ' to kick the tail out';
TIP.drifting = 'Drifting! Keep ' + (touch ? 'GAS' : 'W') + ' held and steer to hold the angle. Assist catches the slide.';
TIP.link = 'Start the next drift before the chain bar empties to raise the multiplier';
TIP.walls = 'Slide close to walls and through the striped zones for bonus points';
TIP.idle = 'Tip: steer into the corner and ' + drift + ', then keep the throttle on';
TIP.idle2 = 'Tip: steer into the corner and ' + drift + ' to start a slide';
