const SKY_VS = [
'varying vec3 vDir;',
'void main() {',
'  vDir = position;',
'  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);',
'}',
].join('\n');
const SKY_FS = [
'uniform vec3 top;',
'uniform vec3 hor;',
'uniform vec3 moonDir;',
'uniform vec3 moonCol;',
'uniform float stars;',
'varying vec3 vDir;',
'float hash(vec3 p) { p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }',
'void main() {',
'  vec3 d = normalize(vDir);',
'  float t = clamp(d.y * 1.6 + 0.04, 0.0, 1.0);',
'  vec3 c = mix(hor, top, pow(t, 0.7));',
'  float m = max(dot(d, moonDir), 0.0);',
'  c += moonCol * (smoothstep(0.9986, 0.9991, m) + pow(m, 80.0) * 0.3 + pow(m, 8.0) * 0.06);',
'  if (stars > 0.5) { float h = hash(floor(d * 230.0)); c += vec3(step(0.9972, h) * smoothstep(0.02, 0.3, d.y) * 0.8); }',
'  gl_FragColor = vec4(c, 1.0);',
'}',
].join('\n');
const PART_VS = [
'attribute float psize;',
'attribute vec3 pcol;',
'uniform float scale;',
'varying vec3 vC;',
'void main() {',
'  vC = pcol;',
'  vec4 mv = modelViewMatrix * vec4(position, 1.0);',
'  gl_PointSize = min(56.0, psize * scale / max(0.6, -mv.z));',
'  gl_Position = projectionMatrix * mv;',
'}',
].join('\n');
const PART_FS = [
'varying vec3 vC;',
'void main() {',
'  vec2 d = gl_PointCoord - vec2(0.5);',
'  float r = dot(d, d) * 4.0;',
'  if (r > 1.0) discard;',
'  float a = 1.0 - r;',
'  gl_FragColor = vec4(vC * (0.35 + a), a);',
'}',
].join('\n');
const DEC_VS = [
'varying vec2 vUv;',
'void main() {',
'  vUv = uv;',
'  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);',
'}',
].join('\n');
