function freshProfile() {
return {
v: 1, cr: 250, earned: 0, ship: 0, owned: [true, false, false],
up: { laser: 0, cargo: 0, thr: 0, hull: 0, fuel: 0, scan: 0, drone: 0 },
lic: [true, false, false, false], cargo: [0, 0, 0, 0, 0, 0], hull: -1, fuel: -1, last: 0, tut: 0,
set: { inv: false, lock: true, sens: 1 }, stats: { rocks: 0, drones: 0, trips: 0 },
};
}
function num(v, d, lo, hi) { v = Number(v); return Number.isFinite(v) ? clamp(v, lo, hi) : d; }
function loadProfile() {
const p = freshProfile();
let raw = null, o = null;
try { raw = typeof api.load === 'function' ? api.load(SAVE_KEY) : null; } catch (e) { raw = null; }
if (typeof raw !== 'string' || !raw) return p;
try { o = JSON.parse(raw); } catch (e) { o = null; }
if (!o || typeof o !== 'object') return p;
p.cr = Math.floor(num(o.cr, p.cr, 0, 1e9));
p.earned = Math.floor(num(o.earned, 0, 0, 1e10));
if (Array.isArray(o.owned)) for (let i = 1; i < 3; i++) p.owned[i] = !!o.owned[i];
p.ship = Math.floor(num(o.ship, 0, 0, 2));
if (!p.owned[p.ship]) p.ship = 0;
if (o.up && typeof o.up === 'object') UPGRADES.forEach(function (u) { p.up[u.key] = Math.floor(num(o.up[u.key], 0, 0, u.max)); });
if (Array.isArray(o.lic)) for (let i = 1; i < 4; i++) p.lic[i] = !!o.lic[i] && p.lic[i - 1];
if (Array.isArray(o.cargo)) for (let i = 0; i < 6; i++) p.cargo[i] = Math.floor(num(o.cargo[i], 0, 0, 100000));
p.hull = num(o.hull, -1, -1, 1e5);
p.fuel = num(o.fuel, -1, -1, 1e5);
p.last = Math.floor(num(o.last, 0, 0, STATIONS.length - 1));
if (!p.lic[STATIONS[p.last].sector]) p.last = 0;
p.tut = Math.floor(num(o.tut, 0, 0, 255));
if (o.set && typeof o.set === 'object') {
p.set.inv = !!o.set.inv; p.set.lock = o.set.lock !== false; p.set.sens = num(o.set.sens, 1, 0.4, 2.5);
}
if (o.stats && typeof o.stats === 'object') {
p.stats.rocks = Math.floor(num(o.stats.rocks, 0, 0, 1e9));
p.stats.drones = Math.floor(num(o.stats.drones, 0, 0, 1e9));
p.stats.trips = Math.floor(num(o.stats.trips, 0, 0, 1e9));
}
return p;
}
