if (prof.up.drone > 0) helperReset(true);
const o = stationObjs[si].grp;
tV.set(0, 0, 27).applyQuaternion(o.quaternion).add(o.position);
ship.pos.copy(tV); ship.q.copy(o.quaternion);
menu.tab = cargoUsed() > 0 ? 0 : 1; menu.row = 0; menu.msgT = 0; menuRepeatKey = '';
prof.stats.trips++;
snd(392, 0.12, { type: 'sine', vol: 0.1 }); snd(523, 0.12, { type: 'sine', vol: 0.1, delay: 0.1 }); snd(784, 0.2, { type: 'sine', vol: 0.1, delay: 0.2 });
toast('Docked at ' + STATIONS[si].name, UI.ok);
