for (let i = 0; i < 2; i++) { const g = gateObjs[i]; if (g.active) radarDot(c, cx, cy, R, scale, g.pos.x, g.pos.y, g.pos.z, g.locked ? UI.danger : UI.cyan, 5, true, 2); }
c.fillStyle = UI.head; c.beginPath(); c.moveTo(cx, cy - 6); c.lineTo(cx + 4.5, cy + 4); c.lineTo(cx - 4.5, cy + 4); c.closePath(); c.fill();
