uTime: {value: 0},uAmb: {value: new THREE.Vector3(0.1,0.1,0.1)},uLampP: {value: new THREE.Vector3()},
uLampC: {value: new THREE.Vector3(1,1,1)},uCamF: {value: new THREE.Vector3(0,0,-1)},uLampR: {value: 17},
uDynP: {value: [new THREE.Vector4(0,-50,0,1),new THREE.Vector4(0,-50,0,1),new THREE.Vector4(0,-50,0,1),new THREE.Vector4(0,-50,0,1)]},
uDynC: {value: [new THREE.Vector3(),new THREE.Vector3(),new THREE.Vector3(),new THREE.Vector3()]},
