'attribute vec4 aC; attribute float aS;',
'uniform float uPx;',
'varying vec4 vC; varying float vFd;',
'void main() {',
'vec4 mv=modelViewMatrix*vec4(position,1.0);',
'gl_PointSize=clamp(aS*uPx/max(-mv.z,0.1),1.0,90.0);',
