for (let i=0;i<9;i++) {
const a=rnd()*TAU,d=rnd()*s*0.18,r=s*(0.12+rnd()*0.16);
blot(g,c+cos(a)*d,c+sin(a)*d,r*1.4,'rgba(255,255,255,0.75)');
}
