if (i!==j) {for (let c=0;c<3;c++) {p[i*3+c]=p[j*3+c];v[i*3+c]=v[j*3+c];r[i*3+c]=r[j*3+c];s[i*3+c]=s[j*3+c];} lf[i]=lf[j];}
