function addTracer(ax,ay,az,bx,by,bz) {
let t=null;
for (let i=0;i<MAX_TRACERS;i++) if (!tracers[i].on) {t=tracers[i];break;}
if (!t) t=tracers[(rnd()*MAX_TRACERS) | 0];
const dx=bx-ax,dy=by-ay,dz=bz-az,l=sqrt(dx*dx+dy*dy+dz*dz)||0.01;
t.on=true;t.x=ax;t.y=ay;t.z=az;t.dx=dx/l;t.dy=dy/l;t.dz=dz/l;t.len=l;t.t=0.07;
}

function hpScale() {return HS.on?1+HS.wave*0.06:1+L.mi*0.05;}
