const oc=OT.on?cellOf(OT.x,OT.z):-1;
if (oc!==L.ocell) {L.ocell=oc;bfs(L.distO,oc,false);}
stepBugs(dt);stepNests(dt);stepQueen(dt);stepAcid(dt);stepShells(dt);stepFires(dt);stepPickups(dt);
