for (let i=0;i<arr.length;i++) {const o=arr[i],d=(o.x-P.x)*(o.x-P.x)+(o.z-P.z)*(o.z-P.z);if (!!o[flag]===want&&d<bd) {bd=d;OT.x=o.x;OT.y=y;OT.z=o.z;OT.on=true;}}
