ctx.fillStyle = on ? NCOL[i] : 'rgba(201, 211, 227, 0.3)'; ctx.beginPath(); ctx.arc(x + 16, ry, 7, 0, TAU); ctx.fill();
tx(ON.name[i] + (i === ON.me ? '  (you)' : ''), x + 34, ry + 1, '700 16px ' + FB, on ? COL.head : 'rgba(201, 211, 227, 0.45)', 'left', w - 170);
tx(!on ? 'left' : i === 0 ? 'host' : 'in the room', x + w - 12, ry + 1, '600 14px ' + FB, on ? COL.body : COL.danger, 'right');
