ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
ctx.beginPath(); ctx.ellipse(x + 2, y + 4, BALL_R, BALL_R * 0.8, 0, 0, TAU); ctx.fill();
ctx.fillStyle = NCOL[i]; ctx.beginPath(); ctx.arc(x, y, BALL_R, 0, TAU); ctx.fill();
ctx.lineWidth = 1.5; ctx.strokeStyle = 'rgba(255, 255, 255, 0.85)'; ctx.stroke();
