tx('THIS HOLE', W - 18, 19, '700 11px ' + FB, COL.body, 'right');
tx('PAR', W - 132, 19, '700 11px ' + FB, COL.body, 'right');
tx(cur + '/' + MAX_STROKES, W - 18, 42, '700 22px ' + FM, cur >= MAX_STROKES - 1 ? COL.danger : COL.head, 'right');
tx(String(hole.def.par), W - 132, 42, '700 22px ' + FM, COL.head, 'right');
