const reducedMotion = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
let viewW = 960, viewH = 600, dpr = 1, hudK = 1, VW = 960, VH = 600;

let destroyed = false, raf = 0, clock = 0;
const disposables = new Set();
function own(o) { disposables.add(o); return o; }
function snd(f, d, o) { try { api.tone(f, d, o); } catch (e) { /* sound is optional */ } }
function noise(d, o) { try { api.noise(d, o); } catch (e) { /* sound is optional */ } }
function tn(f, d, type, vol, slide, delay) { const o = { type: type, vol: vol }; if (slide) o.slide = slide; if (delay) o.delay = delay; snd(f, d, o); }
function nz(d, vol, filter, delay) { const o = { vol: vol, filter: filter }; if (delay) o.delay = delay; noise(d, o); }

