d.vx = rnd(spd * 2); d.vy = 3 + rand() * spd; d.vz = rnd(spd * 2); d.t = 0; d.rx = rand() * 3; d.ry = rand() * 3; d.sp = rnd(10); d.sc = 0.6 + rand() * 0.9;
