d.x = x; d.y = y; d.z = z; d.vx = vx; d.vy = vy; d.vz = vz;
d.rx = Math.random() * TAU; d.ry = Math.random() * TAU; d.rz = 0; d.wx = rand(-9, 9); d.wy = rand(-9, 9); d.wz = rand(-9, 9);
d.sx = sx; d.sy = sy; d.sz = sz; d.life = rand(11, 15); d.rest = false;
