P.ph+=rdt*(2.2+sp*1.6);
let s=M.sin(P.ph),c=M.cos(P.ph),amt=P.ground?clamp(sp/4,0,1):0;
let lean=sp*.02,hipY=-M.abs(c)*.04*amt,twist=0,spin=0,roll=0;
pTHL.rotation.set(s*.7*amt,0,0);pTHR.rotation.set(-s*.7*amt,0,0);
