p.mesh.position.set(px,B.y,pz);p.rot.position.set(px,B.y+1.35,pz);
p.rot.rotation.y+=rdt*(p.w.on?28:3);p.rot.visible=p.w.on||B.st!='ground';
p.w.x=px;p.w.y=B.y;p.w.z=pz;
