S.rank=r;
if(S.comboT>0){S.comboT-=dt;if(S.comboT<=0){if(S.combo>=5){addScore(M.round(M.pow(S.combo,1.3)*4))}S.combo=0}}
if(S.flash>0)S.flash=M.max(0,S.flash-dt*2);
